func run(workers int) time.Duration {
	jobs := make(chan int)
	var wg sync.WaitGroup
	start := time.Now()
	for range workers {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range jobs {
				time.Sleep(50 * time.Millisecond) // one downstream call
			}
		}()
	}
	for i := range 200 {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return time.Since(start)
}

func (s *store) Restore() {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.stopc = make(chan struct{}, 1) // AI: buffer stopc
	s.wg.Add(1)
	go s.worker()
	close(s.stopc)
	s.wg.Wait() // wait for the worker while holding mu
}

func (s *store) worker() {
	defer s.wg.Done()
	s.mu.Lock() // takes the lock before it looks at stopc
	defer s.mu.Unlock()
	select {
	case <-s.stopc:
		return
	default:
	}
}
